                comps[cid] = (c, len(cells)); cid += 1
    return lab, comps

def noise_colors(grid):
    """Colors none of whose 4-connected components has more than one cell."""
    lab, comps = components(grid)
    return {c for c in {v for row in grid for v in row}
            if all(s == 1 for (cc, s) in comps.values() if cc == c)}

def clean_noise(grid):
    """Replace isolated single-cell colors: opposite equal neighbors first, then a 2x2
    completion chosen by tightest bounding box, else the majority orthogonal neighbor."""
    h, w = len(grid), len(grid[0])
    noise = noise_colors(grid)
    if not noise:
        return [row[:] for row in grid]
    lab, comps = components(grid)

    def g(y, x):
        return grid[y][x] if 0 <= y < h and 0 <= x < w and grid[y][x] not in noise else None

    def bbox_slack(cells):
        ys = [y for y, x in cells]; xs = [x for y, x in cells]
        return (max(ys) - min(ys) + 1) * (max(xs) - min(xs) + 1) - len(set(cells))

    out = [row[:] for row in grid]
    for i in range(h):
        for j in range(w):
            if grid[i][j] in noise:
                U, D, L, R = g(i - 1, j), g(i + 1, j), g(i, j - 1), g(i, j + 1)
                if U is not None and U == D:
                    v = U
                elif L is not None and L == R:
                    v = L
                else:
                    cands = []
                    for di in (-1, 0):
                        for dj in (-1, 0):
                            pos = [(i + di, j + dj), (i + di, j + dj + 1),
                                   (i + di + 1, j + dj), (i + di + 1, j + dj + 1)]
                            vals = [g(*p) for p in pos]
                            ci = pos.index((i, j))
                            others = [v2 for k, v2 in enumerate(vals) if k != ci]
                            if None not in others and len(set(others)) == 1:
                                cands.append(others[0])
                    if cands:
                        best = None
                        for c in set(cands):
                            for y, x in ((i - 1, j), (i + 1, j), (i, j - 1), (i, j + 1)):
                                if 0 <= y < h and 0 <= x < w and grid[y][x] == c:
                                    cells = [(y2, x2) for y2 in range(h) for x2 in range(w)
                                             if lab[y2][x2] == lab[y][x]]
                                    break
                            a = bbox_slack(cells + [(i, j)])
                            if best is None or a < best[0]:
                                best = (a, c)
                        v = best[1]
                    else:
                        ns = [x for x in (U, D, L, R) if x is not None]
                        v = Counter(ns).most_common(1)[0][0]
                out[i][j] = v
    return out
